def prod_signs(arr):
    if len(arr) == 0:
        return None

    sum_magnitudes = sum(abs(x) for x in arr)

    sign_product = 1
    has_zero = False

    for num in arr:
        if num == 0:
            has_zero = True
            break

        if num > 0:
            sign_product *= 1
        else:
            sign_product *= -1

    return sum_magnitudes * sign_product

